#include "Quest/AskirQuestComponent.h"
UAskirQuestComponent::UAskirQuestComponent(){PrimaryComponentTick.bCanEverTick=false;} bool UAskirQuestComponent::StartQuest(UAskirQuestData*Q){if(!Q)return false;auto&S=QuestStates.FindOrAdd(Q->QuestID);if(S==EAskirQuestState::Completed||S==EAskirQuestState::Active)return false;S=EAskirQuestState::Active;ActiveObjectives=Q->Objectives;return true;} bool UAskirQuestComponent::AdvanceObjective(FName ID,int32 A){if(ID.IsNone()||A<=0)return false;for(auto&O:ActiveObjectives)if(O.ObjectiveID==ID&&O.CurrentCount<O.RequiredCount){O.CurrentCount=FMath::Min(O.RequiredCount,O.CurrentCount+FMath::Max(0,A));return true;}return false;} bool UAskirQuestComponent::AreObjectivesComplete()const{if(ActiveObjectives.IsEmpty())return false;for(const auto&O:ActiveObjectives)if(O.CurrentCount<O.RequiredCount)return false;return true;} bool UAskirQuestComponent::CompleteQuest(UAskirQuestData*Q){if(!Q||GetState(Q)!=EAskirQuestState::Active||!AreObjectivesComplete())return false;QuestStates.Add(Q->QuestID,EAskirQuestState::Completed);ActiveObjectives.Empty();return true;} EAskirQuestState UAskirQuestComponent::GetState(UAskirQuestData*Q)const{if(Q)if(const auto*S=QuestStates.Find(Q->QuestID))return *S;return EAskirQuestState::Inactive;}
